1957	  const { captureHomepage } = await import("../lib/hosting-thumb");
1958	  const shot = await captureHomepage(hostname);
1959	
1960	  if (!shot.ok) {
1961	    await db.hostingSiteThumb.updateMany({
1962	      where: { accountId: a.id, siteKey },
1963	      data: { status: "FAILED", error: shot.error.slice(0, 200), data: null, sizeBytes: 0 },
1964	    });
1965	    // The TASK succeeded — we asked, and got an answer. The answer is stored on
1966	    // the row, where the card reads it. Failing the task too would put the same
1967	    // message in two places and light up the activity feed red for a site that
1968	    // simply is not published yet.
1969	    return JSON.stringify({ note: `Preview not captured: ${shot.error}` });
1970	  }
