1975	      status: "READY", error: null, mime: shot.mime, data: new Uint8Array(shot.bytes),
1976	      sizeBytes: shot.bytes.length, width: shot.width, height: shot.height,
1977	      capturedAt: new Date(), hostname,
1978	    },
1979	  });
1980	  return JSON.stringify({ note: `Captured ${hostname}` });
1981	}
