1990	  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
1991	  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
1992	  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
1993	  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
