2001	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
2002	    } catch (e) {
2003	      await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
2004	    }
2005	    return;
2006	  }
2007	
2008	  try {
2009	    const conn = await connectNode(a.node);
2010	    try {
2011	      let result: string | null = null;
2012	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
2013	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
